@SpringBootApplication
public class OrdersApplication {
    public static void main(String[] args) {
        SpringApplication.run(OrdersApplication.class, args);
    }
}

@Service
final class OrderService {
    private final OrderRepository orders;
    private final PaymentClient payments;

    OrderService(OrderRepository orders, PaymentClient payments) {
        this.orders = orders;
        this.payments = payments;
    }
}

@Configuration
class ClientConfiguration {
    @Bean PaymentClient paymentClient(HttpClient.Builder builder) { return new HttpPaymentClient(builder.build()); }
}

@ConfigurationProperties("payments")
@Validated
public record PaymentProperties(
    @NotBlank URI baseUrl,
    @DurationMin(seconds = 1) Duration timeout
) {}

record CreateOrderRequest(@NotEmpty List<@Valid LineItemRequest> items) {}

@RestController
@RequestMapping("/orders")
final class OrderController {
    @PostMapping
    ResponseEntity<OrderResponse> create(@Valid @RequestBody CreateOrderRequest request, Principal principal) {
        var order = service.create(principal.getName(), request);
        return ResponseEntity.created(URI.create("/orders/" + order.id())).body(OrderResponse.from(order));
    }
}

@RestControllerAdvice
final class ApiErrors {
    @ExceptionHandler(OrderNotFound.class)
    ProblemDetail notFound(OrderNotFound error) {
        var problem = ProblemDetail.forStatusAndDetail(HttpStatus.NOT_FOUND, "Order not found");
        problem.setProperty("code", "ORDER_NOT_FOUND");
        return problem;
    }
}

@Service
final class CheckoutService {
    @Transactional
    public Order confirm(UUID orderId, UUID actorId) {
        var order = orders.findForUpdate(orderId).orElseThrow(OrderNotFound::new);
        authorization.checkCanConfirm(actorId, order);
        order.confirm();
        outbox.append(OrderConfirmed.from(order));
        return order;
    }
}

@Bean
SecurityFilterChain security(HttpSecurity http) throws Exception {
    return http
        .authorizeHttpRequests(auth -> auth
            .requestMatchers("/actuator/health/**").permitAll()
            .requestMatchers(HttpMethod.POST, "/orders/**").hasAuthority("SCOPE_orders.write")
            .anyRequest().authenticated())
        .oauth2ResourceServer(oauth -> oauth.jwt(Customizer.withDefaults()))
        .build();
}

@WebMvcTest(OrderController.class)
class OrderControllerTest {
    @Autowired MockMvc mvc;
    @MockBean OrderService service;

    @Test void rejectsInvalidOrder() throws Exception {
        mvc.perform(post("/orders").contentType(APPLICATION_JSON).content("{\"items\":[]}"))
           .andExpect(status().isBadRequest());
    }
}
